/* Open/close animations */


/* Overlay fade */
/* overlay at start */
.gva-mfp-fade-in.mfp-bg,
.nm-mfp-zoom-in.mfp-bg {
  opacity: 0;
  -webkit-transition: opacity 0.18s ease-out;
  -moz-transition: opacity 0.18s ease-out;
  transition: opacity 0.18s ease-out;
}
/* overlay animate in */
.gva-mfp-fade-in.mfp-bg.mfp-ready,
.nm-mfp-zoom-in.mfp-bg.mfp-ready {
  opacity: 0.73;
}
/* overlay animate out */
.gva-mfp-fade-in.mfp-bg.mfp-removing,
.nm-mfp-zoom-in.mfp-bg.mfp-removing {
  opacity: 0;
}


/* Modal fade */
/* start state */
.gva-mfp-fade-in .mfp-content {
  opacity: 0;  
  -webkit-transition: opacity 0.18s ease-in-out;
  -moz-transition: opacity 0.18s ease-in-out;
  -o-transition: opacity 0.18s ease-in-out;
  transition: opacity 0.18s ease-in-out;
}
/* animate in */
.gva-mfp-fade-in.mfp-ready .mfp-content {
  opacity: 1;
}
/* animate out */
.gva-mfp-fade-in.mfp-removing .mfp-content {
  opacity: 0; 
}


/* Modal zoom fade */
/* start state */
.nm-mfp-zoom-in .mfp-content {
  opacity: 0;
  -webkit-transition: all 0.18s ease-in-out;
  -moz-transition: all 0.18s ease-in-out;
  -o-transition: all 0.18s ease-in-out;
  transition: all 0.18s ease-in-out;
  -webkit-transform: scale(0.8);
  -moz-transform: scale(0.8);
  -ms-transform: scale(0.8);
  -o-transform: scale(0.8);
  transform: scale(0.8);
  -webkit-transform-origin: top center;
  -moz-transform-origin: top center;
  -o-transform-origin: top center;
  transform-origin: top center;
}
/* animate in */
.nm-mfp-zoom-in.mfp-ready .mfp-content {
  opacity: 1;
  -webkit-transform: scale(1);
  -moz-transform: scale(1);
  -ms-transform: scale(1);
  -o-transform: scale(1);
  transform: scale(1);
}
/* animate out */
.nm-mfp-zoom-in.mfp-removing .mfp-content {
  -webkit-transform: scale(0.8);
  -moz-transform: scale(0.8);
  -ms-transform: scale(0.8);
  -o-transform: scale(0.8);
  transform: scale(0.8);
  opacity: 0; 
}


/* Move-from-top effect (used on the 'register-account' popup) */
/* start state */
.nm-mfp-move-from-top .mfp-content {
	vertical-align: top;
}
.nm-mfp-move-from-top .nm-popup-wrap {
	transition: all 0.2s;
	transform: translateY(-160px);
}
.nm-mfp-move-from-top.mfp-bg {
	opacity: 0;
	transition: all 0.2s;
}
/* animate in */
.nm-mfp-move-from-top.mfp-ready .nm-popup-wrap {
	transform: translateY(0);
}
.nm-mfp-move-from-top.mfp-ready.mfp-bg {
	opacity: 0.9;
}
/* animate out */
.nm-mfp-move-from-top.mfp-removing .nm-popup-wrap {
	opacity: 0;
}
.nm-mfp-move-from-top.mfp-removing.mfp-bg {
	opacity: 0;
}

