.giveform-item-media .content-meta .campaign-category a {
  display: inline-block;
  color: #fff;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.giveform-item-media .content-meta .campaign-category a:hover {
  text-decoration: underline;
