			/* =========================
   EVENTS PAGE DESIGN FIX
   ========================= */

/* Target ONLY event pages */
.single-tribe_events #tribe-events-pg-template {
  max-width: 1100px;
  margin: 40px auto;
  padding: 30px;
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
}

/* Fix container conflicts */
.single-tribe_events #tribe-events-pg-template .container,
.single-tribe_events #tribe-events-pg-template .row {
  all: unset;
}

/* Title Styling */
.single-tribe_events .tribe-events-single-event-title {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: 15px;
  line-height: 1.3;
}

/* Event meta (date, time, etc) */
.single-tribe_events .tribe-events-schedule {
  font-size: 15px;
  color: #666;
  margin-bottom: 20px;
}

/* Main content spacing */
.single-tribe_events .post-single-content {
  margin-top: 20px;
  line-height: 1.7;
  font-size: 16px;
}

/* Venue + Price blocks */
.single-tribe_events .tribe-block {
  padding: 15px;
  margin: 15px 0;
  background: #f8f9fb;
  border-radius: 8px;
}

/* Buttons (subscribe / links) */
.single-tribe_events .tribe-common-c-btn-border {
  padding: 10px 18px;
  border-radius: 6px;
  border: 1px solid #ddd;
  background: #fff;
  transition: 0.3s;
  cursor: pointer;
}

.single-tribe_events .tribe-common-c-btn-border:hover {
  background: #000;
  color: #fff;
  border-color: #000;
}

/* Dropdown fix */
.single-tribe_events .tribe-events-c-subscribe-dropdown__content {
  border-radius: 8px;
  box-shadow: 0 8px 20px rgba(0,0,0,0.1);
}

/* Footer spacing */
.single-tribe_events #tribe-events-footer {
  margin-top: 40px;
}

/* Fix flex breaking issues */
.single-tribe_events .tribe-events-single,
.single-tribe_events .tribe-events-content {
  display: block !important;
}

/* Image fix */
.single-tribe_events img {
  max-width: 100%;
  height: auto;
  border-radius: 10px;
}

/* Mobile responsive */
@media (max-width: 768px) {
  .single-tribe_events #tribe-events-pg-template {
    padding: 20px;
    margin: 20px;
  }

  .single-tribe_events .tribe-events-single-event-title {
    font-size: 24px;
  }
}










/* =========================
   EVENTS LIST PAGE DESIGN
   ========================= */

/* Scope only plugin pages */
.post-type-archive-tribe_events .tribe-events-calendar-list,
.tribe-events-page-template .tribe-events-calendar-list {
  max-width: 1100px;
  margin: 40px auto;
  padding: 0 15px;
}

/* Each event card */
.tribe-events-calendar-list li {
  list-style: none;
  margin-bottom: 30px;
}

/* Card container */
.tribe-event-list-block {
  display: flex;
  gap: 25px;
  background: #fff;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 8px 25px rgba(0,0,0,0.08);
  transition: 0.3s;
}

/* Hover effect */
.tribe-event-list-block:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 35px rgba(0,0,0,0.12);
}

/* LEFT SIDE (Image + Date) */
.tribe-event-left {
  width: 220px;
  min-width: 220px;
}

/* Event image */
.tribe-events-event-image img {
  width: 100%;
  height: auto;
  border-radius: 10px;
}

/* Date styling */
.tribe-start-date {
  margin-top: 10px;
  font-weight: 600;
  font-size: 14px;
  color: #555;
}

/* RIGHT SIDE (Content) */
.tribe-event-right {
  flex: 1;
}

/* Title */
.tribe-events-list-event-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 10px;
  line-height: 1.4;
}

/* Meta (time/location) */
.tribe-events-event-meta {
  font-size: 14px;
  color: #777;
  margin-bottom: 10px;
}

/* Description */
.entry-summary {
  font-size: 15px;
  line-height: 1.6;
  color: #444;
}

/* CTA Button */
.event-action {
  margin-top: 15px;
}

.event-action a {
  display: inline-block;
  padding: 10px 18px;
  background: #000;
  color: #fff;
  border-radius: 6px;
  text-decoration: none;
  transition: 0.3s;
}

.event-action a:hover {
  background: #333;
}

/* Fix clearfix issues */
.tribe-event-list-block::after {
  content: "";
  display: block;
  clear: both;
}

/* REMOVE unwanted floats */
.tribe-event-left,
.tribe-event-right {
  float: none !important;
}

/* Mobile responsive */
@media (max-width: 768px) {
  .tribe-event-list-block {
    flex-direction: column;
  }

  .tribe-event-left {
    width: 100%;
  }

  .tribe-events-list-event-title {
    font-size: 18px;
  }
}		

